class FinanceAssetGainIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;
 static FinanceAssetGainService gains;static FinanceAccountingService accounting;static FinanceLedgerGovernance governance;static FinanceControlService control;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");static final LocalDate DAY=LocalDate.of(2026,10,24);
 @TempDir Path originalRoot;
 UUID hotel,company,owner,finance,director,poster,physical,book;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var source=pg.getPostgresDatabase();jdbc=new JdbcTemplate(source);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(source).locations("classpath:db/migration").target("112").load().migrate();named=new NamedParameterJdbcTemplate(source);var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var mapper=new ObjectMapper().findAndRegisterModules();var audit=new AuditWriter(named,e->{});tx=new TransactionTemplate(new DataSourceTransactionManager(source));accounting=new FinanceAccountingService(named,db,access,audit,mapper);governance=new FinanceLedgerGovernance(named,db,access,accounting);control=new FinanceControlService(named,db,access,null,null,null);gains=new FinanceAssetGainService(named,db,access,accounting,audit);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}@AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();owner=user();finance=user();director=user();poster=user();physical=UUID.randomUUID();book=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'盘盈真实门店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'盘盈实际法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,payable_account,enabled) values(?,?,?,?,?,?,?,?,2,'AP',true)",T,hotel,company,user(),finance,director,user(),user());jdbc.update("insert into store_fixed_asset(id,tenant_id,hotel_org_unit_id,asset_code,name,category) values(?,?,?,?, '盘点确证的原实物','设备')",physical,T,hotel,physical.toString());as(owner,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"盘盈真实账套",DAY.withDayOfMonth(1))));for(String code:List.of("ASSET","CIP","DEP","EXP","GAIN")){UUID proposal=UUID.randomUUID();as(owner,"*");call(()->governance.account(proposal,new FinanceAccountingModels.Account(book,code,code,code.equals("EXP")?"EXPENSE":code.equals("GAIN")?"EQUITY":"ASSET",Set.of("GAIN","DEP").contains(code)?"CREDIT":"DEBIT",code,false,true,-1),"真实盘盈政策科目"));as(poster,"*");call(()->governance.publish(proposal,new FinanceControlModels.Version(0,"独立真实科目发布"),false));}UUID policy=UUID.randomUUID();as(owner,"finance.configure");call(()->control.savePolicy(new FinanceControlModels.Policy(policy,hotel,"CATEGORY","gain-asset","真实盘盈资产类别",DAY.withDayOfMonth(1),null,Map.of("items",List.of(Map.of("code","ACTUAL_ASSET","name","实际设备资产","treatment","ASSET"))))));as(finance,"finance.configure");call(()->control.publishPolicy(policy,new FinanceControlModels.Version(0,"独立确认资产分类"),false));as(owner,"*");}
 @Test void originalProofIndependentReviewActualPostingAndSingleCardNeverInventCashOrPurchase()throws Exception{UUID gain=create();byte[] original=upload(gain);submit(gain);as(finance,"*");UUID voucher=UUID.randomUUID();var command=new Review(voucher,2,true,"独立核对估值原件与主体会计政策");call(()->gains.review(gain,command));call(()->gains.review(gain,command));assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_type='FS_ASSET_GAIN' and source_id=?",Integer.class,gain)).isOne();assertThat(jdbc.queryForObject("select status from fa_voucher where id=?",String.class,voucher)).isEqualTo("DRAFT");assertThatThrownBy(()->call(()->gains.card(gain,card(UUID.randomUUID())))).hasMessageContaining("尚未独立过账");post(voucher);as(owner,"*");UUID card=UUID.randomUUID();call(()->gains.card(gain,card(card)));call(()->gains.card(gain,card(card)));assertThatThrownBy(()->call(()->accounting.reverse(voucher,new FinanceAccountingModels.Reverse(UUID.randomUUID(),2,DAY,"不得孤立红冲已承接真实资产的盘盈原值")))).hasMessageContaining("资产卡片");assertThat(jdbc.queryForObject("select original_value from fs_asset_card where gain_id=?",BigDecimal.class,gain)).isEqualByComparingTo("1234.56");assertThat(jdbc.queryForObject("select physical_asset_id from fs_asset_card where gain_id=?",UUID.class,gain)).isEqualTo(physical);assertThatThrownBy(this::create).hasMessageContaining("已有财务卡");assertThatThrownBy(()->call(()->gains.card(gain,new Card(card,"篡改原编号",BigDecimal.ZERO,12,DAY,"CIP","DEP","EXP")))).hasMessageContaining("不同冻结内容");assertThat(jdbc.queryForObject("select count(*) from fo_document where hotel_id=?",Integer.class,hotel)).isZero();assertThat(jdbc.queryForObject("select count(*) from finance_expense_entry where hotel_id=?",Integer.class,hotel)).isZero();UUID attachment=jdbc.queryForObject("select id from fs_asset_gain_original where gain_id=?",UUID.class,gain);assertThat(call(()->evidence().download(gain,attachment)).resource().getContentAsByteArray()).containsExactly(original);assertThat(call(()->FinanceCloseV2.extraChecks(named,TenantContext.require(),jdbc.queryForMap("select * from fa_book where id=?",book),DAY.withDayOfMonth(1))).stream().filter(c->c.get("code").equals("V2_ASSET_GAIN")).findFirst().orElseThrow()).containsEntry("passed",true);}
 @Test void originalPreparerAndUnconfiguredReviewerCannotSelfApprove(){UUID gain=create();upload(gain);submit(gain);as(owner,"*");assertThatThrownBy(()->call(()->gains.review(gain,new Review(UUID.randomUUID(),2,true,"本人不可自审")))).hasMessageContaining("独立财务");as(user(),"finance.read","finance.review","finance.accounting.write");assertThatThrownBy(()->call(()->gains.review(gain,new Review(UUID.randomUUID(),2,true,"同店非指派不能代审")))).hasMessageContaining("冻结配置");assertThat(jdbc.queryForObject("select status from fs_asset_gain where id=?",String.class,gain)).isEqualTo("PENDING");}
 @Test void missingOriginalCannotSubmitAndPhysicalRegistrationAloneCreatesNoGain(){UUID gain=create();assertThatThrownBy(()->call(()->gains.submit(gain,new Command(UUID.randomUUID(),0,"仅文字不能当原件")))).hasMessageContaining("真实估值");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_type='FS_ASSET_GAIN' and source_id=?",Integer.class,gain)).isZero();assertThat(jdbc.queryForObject("select count(*) from fs_asset_card where physical_asset_id=?",Integer.class,physical)).isZero();}
 @Test void samePhysicalIdentityCannotBeReservedTwiceAndCancelledWrongDraftRetainsHistory(){UUID first=create();assertThatThrownBy(this::create).hasMessageContaining("已有未作废");call(()->gains.cancel(first,new Command(UUID.randomUUID(),0,"原估值输入错误，保留原件另建")));UUID second=create();assertThat(second).isNotEqualTo(first);assertThat(jdbc.queryForObject("select status from fs_asset_gain where id=?",String.class,first)).isEqualTo("CANCELLED");}
 @Test void crossingHotelOrTenantCannotReadOriginalOrApprove(){UUID gain=create();TenantContext.set(new TenantPrincipal(T,finance,"GAIN_TEST",Set.of("TEST"),Set.of("finance.read","finance.review","finance.accounting.write"),Set.of(UUID.randomUUID()),Set.of(),false,UUID.randomUUID()));assertThatThrownBy(()->call(()->gains.detail(gain))).isInstanceOf(AccessDeniedException.class);call(()->{jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,UUID.randomUUID().toString());assertThat(jdbc.queryForObject("select count(*) from fs_asset_gain where id=?",Integer.class,gain)).isZero();return null;});as(owner,"finance.accounting.write");assertThatThrownBy(()->call(()->gains.detail(gain))).isInstanceOf(AccessDeniedException.class);}
 @Test void approvedValuationAndOriginalMetadataAreImmutableAndPhysicalDriftStopsApproval(){UUID gain=create();upload(gain);submit(gain);jdbc.update("update store_fixed_asset set name='另一次资产变更',row_version=row_version+1 where id=?",physical);as(finance,"*");assertThatThrownBy(()->call(()->gains.review(gain,new Review(UUID.randomUUID(),2,true,"原快照不再一致")))).hasMessageContaining("快照已变化");assertThatThrownBy(()->jdbc.update("update fs_asset_gain set value=100,version=version+1 where id=?",gain)).hasMessageContaining("cannot be overwritten");assertThatThrownBy(()->jdbc.update("update fs_asset_gain_original set sha256=? where gain_id=?","f".repeat(64),gain)).hasMessageContaining("append-only");}
 @Test void missingOrTamperedStoredBytesBlockHttpApprovalWithoutChangingSubmittedValuation()throws Exception{UUID gain=create();upload(gain);submit(gain);String key=jdbc.queryForObject("select object_key from fs_asset_gain_original where gain_id=?",String.class,gain);Files.write(originalRoot.resolve(key),new byte[]{1,2,3});as(finance,"*");var controller=new FinanceAssetGainController(gains,evidence());assertThatThrownBy(()->call(()->controller.review(gain,new Review(UUID.randomUUID(),2,true,"不得对篡改原件审核通过")))).hasMessageContaining("指纹不符");assertThat(jdbc.queryForObject("select status from fs_asset_gain where id=?",String.class,gain)).isEqualTo("PENDING");}
 @Test void concurrentSameDraftRequestHasOnePhysicalValuation(){Draft input=input(UUID.randomUUID());var pool=Executors.newFixedThreadPool(2);try{var tasks=List.of(pool.submit(()->{as(owner,"*");return call(()->gains.create(input));}),pool.submit(()->{as(owner,"*");return call(()->gains.create(input));}));for(var task:tasks)assertThatCode(()->task.get(30,TimeUnit.SECONDS)).doesNotThrowAnyException();assertThat(jdbc.queryForObject("select count(*) from fs_asset_gain where physical_asset_id=?",Integer.class,physical)).isOne();}finally{pool.shutdownNow();}}
 @Test void gainAndSubsequentDepreciationInheritActualDepartmentWithoutGuessingAssetDefaults(){
  UUID gain=create();upload(gain);submit(gain);as(finance,"*");UUID voucher=UUID.randomUUID();call(()->gains.review(gain,new Review(voucher,2,true,"真实部门及实际盘盈原件核对")));post(voucher);as(owner,"*");UUID card=UUID.randomUUID();call(()->gains.card(gain,card(card)));assertThat(jdbc.queryForObject("select count(*) from fa_voucher_line where voucher_id=? and auxiliary#>>'{department,id}'=?",Integer.class,voucher,hotel.toString())).isEqualTo(2);
  var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var mapper=new ObjectMapper().findAndRegisterModules();var audit=new AuditWriter(named,e->{});var stock=new cn.sifangguan.hotelaios.storeassets.StoreResourceService(named,db,access,new EffectiveIdentityService(named,db),audit,mapper,new cn.sifangguan.hotelaios.storeassets.StoreItemUsageScopes(named));var supply=new FinanceSupplyService(named,db,access,mapper,audit,accounting,new cn.sifangguan.hotelaios.storeassets.StoreFinanceBridge(named,stock,access),new FinanceOperationsService(named,db,access,mapper,audit,accounting));UUID depreciation=UUID.randomUUID();as(finance,"*");call(()->supply.assetEvent(card,new FinanceSupplyModels.AssetEvent(depreciation,0,"DEPRECIATE",DAY,null,null,BigDecimal.ZERO,BigDecimal.ZERO,null,null,null,null,"本期真实折旧继承原盘盈实际部门")));assertThat(jdbc.queryForObject("select count(*) from fa_voucher_line where voucher_id=? and auxiliary#>>'{department,id}'=?",Integer.class,depreciation,hotel.toString())).isEqualTo(2);assertThat(jdbc.queryForObject("select sum(debit)-sum(credit) from fa_voucher_line where voucher_id=?",BigDecimal.class,depreciation)).isZero();
 }
 @Test void actualBackupOriginalIndexSqlExecutesAgainstOwnerConnectionAndCurrentSchema()throws Exception{
  UUID gain=create();byte[] actualOriginal=upload(gain);UUID task=UUID.randomUUID(),assignment=UUID.randomUUID(),link=UUID.randomUUID(),local=UUID.randomUUID(),order=UUID.randomUUID(),purged=UUID.randomUUID(),active=UUID.randomUUID();String localKey=T+"/work-records/"+task+"/"+local+".pdf",activeKey=T+"/procurement/"+order+"/"+active+".pdf";for(String key:List.of(localKey,activeKey)){Path file=originalRoot.resolve("work-storage").resolve(key);Files.createDirectories(file.getParent());Files.write(file,actualOriginal);}
  UUID employee=jdbc.queryForObject("select id from employee where tenant_id=? limit 1",UUID.class,T),position=jdbc.queryForObject("select id from position_definition where tenant_id=? limit 1",UUID.class,T);jdbc.update("insert into employee_position_assignment(id,tenant_id,employee_id,org_unit_id,position_id,valid_from) values(?,?,?,?,?,?)",assignment,T,employee,hotel,position,DAY);jdbc.update("insert into management_task(id,tenant_id,task_no,idempotency_key,org_unit_id,title,created_by) values(?,?,?,?,?,'原件备份真实链接/本地文件边界',?)",task,T,task.toString(),task.toString(),hotel,owner);
  jdbc.update("insert into task_evidence(id,tenant_id,task_id,submitted_by_assignment_id,evidence_type,object_key) values(?,?,?,?,'LINK','https://example.invalid/external-reference')",link,T,task,assignment);jdbc.update("insert into task_evidence(id,tenant_id,task_id,submitted_by_assignment_id,evidence_type,object_key,size_bytes,sha256) values(?,?,?,?,'FILE',?,?,?)",local,T,task,assignment,localKey,actualOriginal.length,FinanceService.hash(actualOriginal));jdbc.update("insert into procurement_order(id,tenant_id,hotel_id,source,status,applicant_id,title) values(?,?,?,'REQUEST','DRAFT',?,'合法已清理与有效采购原件并存')",order,T,hotel,owner);
  for(UUID id:List.of(purged,active))jdbc.update("insert into procurement_attachment(id,tenant_id,order_id,original_name,media_type,size_bytes,sha256,object_key,scan_status,uploaded_by,purged_at) values(?,?,?,'实际原文件.pdf','application/pdf',?,?,?,'CLEAN',?,?)",id,T,order,actualOriginal.length,FinanceService.hash(actualOriginal),id.equals(active)?activeKey:T+"/procurement/"+order+"/"+purged+".pdf",owner,id.equals(purged)?java.sql.Timestamp.valueOf(DAY.atStartOfDay()):null);
  Path repository=Path.of(System.getProperty("user.dir")).toAbsolutePath();while(repository!=null&&!Files.isRegularFile(repository.resolve("infra/production/backup/core-originals-reference.sql")))repository=repository.getParent();assertThat(repository).isNotNull();String sql=Files.readString(repository.resolve("infra/production/backup/core-originals-reference.sql"));if(sql.startsWith("\\set ON_ERROR_STOP on"))sql=sql.substring(sql.indexOf('\n')+1);String payload=null;
  try(var connection=Objects.requireNonNull(jdbc.getDataSource()).getConnection();var statement=connection.createStatement()){
   boolean result=statement.execute(sql);while(true){if(result){try(var set=statement.getResultSet()){while(set.next())payload=set.getString(1);}}else if(statement.getUpdateCount()==-1)break;result=statement.getMoreResults();}
  }
  assertThat(payload).contains("fs_asset_gain_original",gain.toString(),"FINANCE",local.toString(),active.toString()).doesNotContain(link.toString(),purged.toString(),"https://example.invalid");assertThat(jdbc.queryForObject("select count(*) from pg_class where relnamespace='public'::regnamespace and relname in ('attachment','task_evidence','daily_report_evidence','procurement_attachment','daily_activity_photo','ai_evidence_sample','ai_evidence_photo','academy_course','finance_attachment','fo_attachment','fb_attachment','fs_asset_gain_original','finance_invoice_intake')",Integer.class)).isEqualTo(13);
 }
 private FinanceAssetGainEvidenceService evidence(){return new FinanceAssetGainEvidenceService(originalRoot.toString(),gains,new AccessPolicy(),FinanceOriginalScannerFixture.cleanScanner());}
 private UUID create(){as(owner,"*");UUID id=UUID.randomUUID();call(()->gains.create(input(id)));return id;}
 private Draft input(UUID id){return new Draft(id,book,physical,hotel,"ACTUAL_ASSET",DAY,DAY,new BigDecimal("1234.56"),"ASSET","GAIN","实际盘点证明及可核对估值构成","本主体已独立确认盘盈财务政策，非系统代替估值专家");}
 private byte[] upload(UUID gain){try(var doc=new PDDocument();var bytes=new ByteArrayOutputStream()){doc.addPage(new PDPage());doc.save(bytes);byte[] original=bytes.toByteArray();as(owner,"*");call(()->evidence().upload(gain,UUID.randomUUID(),new MockMultipartFile("file","实际估值依据.pdf","application/pdf",original)));return original;}catch(Exception e){throw new RuntimeException(e);}}
 private void submit(UUID gain){as(owner,"*");call(()->gains.submit(gain,new Command(UUID.randomUUID(),1,"实际原件齐全，提交独立核对")));}
 private Card card(UUID id){return new Card(id,"盘盈卡-"+id,BigDecimal.ZERO,12,DAY,"CIP","DEP","EXP");}
 private void post(UUID voucher){as(poster,"*");call(()->accounting.review(voucher,0));call(()->accounting.post(voucher,1));}
 private UUID user(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'盘盈独立人员')",id,T,id.toString());return id;}
 private void as(UUID actor,String...permissions){TenantContext.set(new TenantPrincipal(T,actor,"GAIN_TEST",Set.of("TEST"),Set.of(permissions),Set.of(hotel),Set.of(),false,UUID.randomUUID()));}
 private static <R>R call(Supplier<R> body){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");new TenantDatabaseContext(jdbc,true).apply(TenantContext.require().tenantId());return body.get();});}
}
